// Load the real, animated GLB asset generated by GitHub Actions.
// This replaces procedural meshes, while keeping Race Lab's physics, camera,
// speed, positions, labels and 2D fallback untouched.
const STATUS_ID='design-glb-status';
function status(text,failed=false){
 const e=document.getElementById(STATUS_ID);
 if(e){e.textContent=text;e.style.color=failed?'#ffc6a3':'#a1ead4'}
}
function numberMaterial(THREE,material,num){
 const canvas=document.createElement('canvas');
 canvas.width=384;canvas.height=320;
 const ctx=canvas.getContext('2d');
 ctx.fillStyle='#1556d9';ctx.fillRect(0,0,384,320);
 ctx.strokeStyle='#ffffff';ctx.lineWidth=18;
 ctx.strokeRect(11,11,362,298);
 ctx.fillStyle='#ffffff';ctx.textAlign='center';ctx.textBaseline='middle';
 ctx.font=num<10?'900 236px Arial':'900 177px Arial';
 ctx.fillText(String(num),192,165);
 const texture=new THREE.CanvasTexture(canvas);
 texture.colorSpace=THREE.SRGBColorSpace;
 texture.anisotropy=2;
 const mat=material.clone();mat.map=texture;mat.color.set('#ffffff');mat.needsUpdate=true;
 return {mat,texture};
}
function styleModel(THREE,model,appearance){
 const names=new Set(['coat','lightcoat','nose','blue','deepblue','Saddlecloth4']);
 const materialCopies=new Map(),byName=new Map();
 let numTexture=null;
 model.assetRoot.traverse(o=>{
   if(!o.isMesh)return;
   const original=o.material;
   const name=original?.name;
   if(!names.has(name))return;
   if(!materialCopies.has(original)){
     const changed=name==='Saddlecloth4'?numberMaterial(THREE,original,model.id).mat:original.clone();
     if(name==='Saddlecloth4')numTexture=changed.map;
     materialCopies.set(original,changed);
     byName.set(name,changed);
   }
   o.material=materialCopies.get(original);
 });
 model.assetStyle={byName,numTexture,count:-1};
 updateDesign01GLBAppearance(THREE,model,appearance);
}
export function updateDesign01GLBAppearance(THREE,model,appearance,fieldCount){
 const record=model.assetStyle;
 if(!record)return;
 if(record.count===fieldCount)return;
 const mats=record.byName;
 const set=(name,c)=>mats.get(name)?.color.set(c);
 set('coat',appearance.coat);
 set('lightcoat',new THREE.Color(appearance.coat).multiplyScalar(1.13));
 set('nose',new THREE.Color(appearance.coat).multiplyScalar(1.33));
 set('blue',appearance.helmet);
 set('deepblue',new THREE.Color(appearance.helmet).multiplyScalar(.54));
 record.count=fieldCount;
}
export async function loadDesign01GLB(THREE,models,getAppearance){
 status('Design 01：3Dモデル読込中');
 const {GLTFLoader}=await import('three/addons/loaders/GLTFLoader.js');
 const gltf=await new GLTFLoader().loadAsync('./assets/Design01_animated.glb');
 if(!gltf.scene||!gltf.animations?.length)throw new Error('GLBに走行アニメーションがありません');
 for(const model of models){
   const next=gltf.scene.clone(true);
   next.name='Design01_GLBRacer_'+model.id;
   next.scale.set(.82,.82,.82);
   // Change each runner's appearance independently while sharing GPU geometry.
   model.assetRoot=next;
   styleModel(THREE,model,getAppearance(model.id,18));
   model.assetStyle.count=18;
   const mixer=new THREE.AnimationMixer(next);
   const action=mixer.clipAction(gltf.animations[0]);
   action.setLoop(THREE.LoopRepeat,Infinity);
   action.play();
   model.assetMixer=mixer;
   // Keep only the horse label from the old procedural character tree.
   for(const child of [...model.group.children]){
     if(child!==model.nameLabel?.sprite)model.group.remove(child);
   }
   model.group.add(next);
   model.nativeDesign01=true;
 }
 status('Design 01：GLB適用済み（18頭）');
 return {horseCount:models.length,animation:gltf.animations[0].name};
}
